"""Comparison with the reference data generated by MATLAB.

The MAT-files in code/python/refdata are generated by
code/python/tools/matlab/gen_refdata.m:
    layers/   : lsunIntermediateRotation2dLayer with BoundaryOperation
                'Circular' and 'Termination'
    networks/ : the analyzer and synthesizer of fcn_createlsunlgraph2d

Conversions from MATLAB to PyTorch:
    coefficients : nChs x nRows x nCols x nSamples -> nSamples x nRows x nCols x nChs
    images       : H x W x 1 x nSamples (SSCB)      -> nSamples x 1 x H x W
    subbands     : nRows x nCols x C x nSamples     -> nSamples x nRows x nCols x C
    angles, mus  : n x nBlocks (column-major)       -> nBlocks x n (row-major)
    layer names  : 'Lv1_Cmp1_Vh1'                   -> 'Lv1_Vh1'

Requirements: Python 3.10-12.x, PyTorch 2.3/4.x

Copyright (c) 2026, Shogo MURAMATSU

All rights reserved.

Contact address: Shogo MURAMATSU,
    Faculty of Engineering, Niigata University,
    8050 2-no-cho Ikarashi, Nishi-ku,
    Niigata, 950-2181, JAPAN

https://www.eng.niigata-u.ac.jp/~msiplab/
"""

import pathlib

import numpy as np
import pytest
import torch

from torch_tansacnet.lsunAnalysis2dNetwork import LsunAnalysis2dNetwork
from torch_tansacnet.lsunIntermediateRotation2dLayer import LsunIntermediateRotation2dLayer

scipy_io = pytest.importorskip("scipy.io")

REFDATA = pathlib.Path(__file__).resolve().parents[1] / "refdata"
DT = torch.float64
CPU = torch.device("cpu")
RTOL, ATOL = 1e-9, 1e-10


def _files(group):
    files = sorted((REFDATA / group).glob("*.mat"))
    if not files:
        pytest.skip(f"No reference data in {REFDATA / group}; run gen_refdata.m")
    return files


def _load(path):
    return scipy_io.loadmat(path)


def _text(m, key):
    v = m[key]
    return str(v[0]) if v.size else ""


def _ints(m, key):
    return [int(v) for v in np.asarray(m[key]).ravel()]


def _coefs(a):
    """nChs x nRows x nCols x nSamples -> nSamples x nRows x nCols x nChs"""
    a = np.asarray(a, dtype=np.float64)
    if a.ndim == 3:
        a = a[..., np.newaxis]
    return torch.from_numpy(np.ascontiguousarray(a.transpose(3, 1, 2, 0)))


def _sscb(a):
    """nRows x nCols x C x nSamples (SSCB) -> nSamples x nRows x nCols x C"""
    a = np.asarray(a, dtype=np.float64)
    while a.ndim < 4:
        a = a[..., np.newaxis]
    return torch.from_numpy(np.ascontiguousarray(a.transpose(3, 0, 1, 2)))


def _image(a):
    """H x W x 1 x nSamples -> nSamples x 1 x H x W"""
    a = np.asarray(a, dtype=np.float64)
    while a.ndim < 4:
        a = a[..., np.newaxis]
    return torch.from_numpy(np.ascontiguousarray(a.transpose(3, 2, 0, 1)))


def _blockwise(a, nblocks):
    """n x (nRows*nCols) in column-major block order -> (nRows*nCols) x n in
    row-major block order. A single column is repeated for all blocks."""
    nrows, ncols = nblocks
    a = np.asarray(a, dtype=np.float64)
    if a.ndim == 1:
        a = a[:, np.newaxis]
    if a.shape[1] == 1:
        a = np.repeat(a, nrows * ncols, axis=1)
    # a[:, r + c*nrows] -> b[r*ncols + c, :]
    b = a.reshape(a.shape[0], ncols, nrows).transpose(2, 1, 0).reshape(nrows * ncols, a.shape[0])
    return torch.from_numpy(np.ascontiguousarray(b))


# --- Layers -------------------------------------------------------------------


@pytest.mark.parametrize("path", _files("layers") if (REFDATA / "layers").is_dir() else [], ids=lambda p: p.stem)
def test_intermediate_rotation_layer(path):
    m = _load(path)
    stride = _ints(m, "meta_stride")
    nblocks = _ints(m, "meta_number_of_blocks")
    direction = _text(m, "meta_direction") or None
    layer = LsunIntermediateRotation2dLayer(
        stride=stride,
        number_of_blocks=nblocks,
        mode=_text(m, "meta_mode"),
        boundary_operation=_text(m, "meta_boundary_operation"),
        direction=direction,
        dtype=DT,
        device=CPU,
    )
    layer.angles = _blockwise(m["angles"], nblocks)
    layer.mus = _blockwise(m["mus"], nblocks)

    X = _coefs(m["x"]).requires_grad_(True)
    Z = layer(X)
    torch.testing.assert_close(Z, _coefs(m["z"]), rtol=RTOL, atol=ATOL)

    (Z * _coefs(m["dldz"])).sum().backward()
    torch.testing.assert_close(X.grad, _coefs(m["dldx"]), rtol=RTOL, atol=ATOL)
    dLdW = layer.orthTransUnx.orthonormalTransforms.angles.grad
    torch.testing.assert_close(dLdW, _blockwise(m["dldw"], nblocks), rtol=1e-8, atol=1e-9)


# --- Networks -----------------------------------------------------------------


def _analyzer(m):
    stride = _ints(m, "meta_stride")
    szIn = _ints(m, "meta_input_size")
    net = LsunAnalysis2dNetwork(
        input_size=szIn,
        stride=stride,
        overlapping_factor=_ints(m, "meta_overlapping_factor"),
        no_dc_leakage=True,
        number_of_levels=1,
        boundary_operation=_text(m, "meta_boundary_operation"),
        dtype=DT,
        device=CPU,
    )
    nblocks = [szIn[0] // stride[0], szIn[1] // stride[1]]
    modules = dict(net.layers[0].named_children())
    for name in _text(m, "meta_layer_names").split(","):
        key = name.replace("Cmp1_", "")
        layer = modules[key]
        layer.angles = _blockwise(m["angles_" + name], nblocks)
        layer.mus = _blockwise(m["mus_" + name], nblocks)
    return net


@pytest.mark.parametrize(
    "path", _files("networks") if (REFDATA / "networks").is_dir() else [], ids=lambda p: p.stem
)
def test_network(path):
    m = _load(path)
    analyzer = _analyzer(m)
    synthesizer = analyzer.T
    with torch.no_grad():
        dc, ac = analyzer(_image(m["x"]))
        torch.testing.assert_close(ac, _sscb(m["ac"]), rtol=RTOL, atol=ATOL)
        torch.testing.assert_close(dc, _sscb(m["dc"]), rtol=RTOL, atol=ATOL)
        Y = synthesizer((_sscb(m["s_dc"]), _sscb(m["s_ac"])))
        torch.testing.assert_close(Y, _image(m["y"]), rtol=RTOL, atol=ATOL)
